#!/usr/bin/env python3
"""Standalone Colab/Linux video example. No original ZIP or helper upload needed.

CLI: python THIS_FILE.py
     python THIS_FILE.py --action setup
     python THIS_FILE.py --action run --image /content/my_image.png

You can also paste this entire file into ONE Colab Python cell and run it.
Select an NVIDIA GPU first. The current Ubuntu OS is reused; uv installs a
private Python and model environment. A GPU is required for model inference.
"""
# Optional settings for pasting directly into a Colab cell. CLI flags override them.
ACTION = "all"                  # all = install/check/download/example; setup; run
INPUT_IMAGE = ""                # Empty = bundled example
DRIVING_VIDEO = ""              # One-to-All only; empty = bundled official driver
PROMPT = None                   # None = model-specific example prompt
WIDTH = HEIGHT = FRAMES = STEPS = SEED = None  # None = model-specific defaults
AUTO_DOWNLOAD = True            # Colab only: download results/logs ZIP at the end
EXPERIMENTAL_T4 = False          # One-to-All only: unsupported experimental FP16 route

from pathlib import Path
import argparse, base64, csv, hashlib, io, json, os, platform, re, shutil
import signal, subprocess, sys, time, traceback, uuid, zipfile


def in_notebook():
    try:
        from IPython import get_ipython
        return get_ipython() is not None
    except ImportError:
        return False


def arguments():
    p=argparse.ArgumentParser(description=MODEL['label']+' — standalone isolated uv runner',
        epilog='Example media, scripts and locked dependencies are embedded as ZIP DATA. Model weights are downloaded on first run. GPU inference has not been tested on the build host.')
    p.add_argument('--action',choices=['all','setup','run','extract','info'],default=ACTION)
    p.add_argument('--root',type=Path,help='Model work directory; each model gets its own venv')
    p.add_argument('--image',default=INPUT_IMAGE)
    p.add_argument('--driver',default=DRIVING_VIDEO,help='One-to-All driving video override')
    p.add_argument('--prompt',default=PROMPT)
    for key,default in [('width',WIDTH),('height',HEIGHT),('frames',FRAMES),('steps',STEPS),('seed',SEED)]:
        p.add_argument('--'+key,type=int,default=default)
    p.add_argument('--fps',type=int)
    p.add_argument('--offload',choices=['sequential','model'])
    p.add_argument('--force',action='store_true',help='Generate a new result even if this exact example already completed')
    p.add_argument('--prepare-only',action='store_true',help='One-to-All: produce pose preview and stop before generation')
    p.add_argument('--run-custom',action='store_true',help='One-to-All: generate from custom inputs after inspecting pose previews')
    p.add_argument('--experimental-t4',action='store_true',default=EXPERIMENTAL_T4,
        help='One-to-All only: explicitly choose unverified FP16+CPU offload; may fail/OOM')
    p.add_argument('--no-download',action='store_true',help='Skip automatic Colab browser download')
    source=globals().get('__file__')
    running_script=bool(source) and Path(sys.argv[0]).resolve()==Path(source).resolve()
    return p.parse_args([] if in_notebook() and not running_script else None)


def digest(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for chunk in iter(lambda:f.read(8*1024*1024),b''):h.update(chunk)
    return h.hexdigest()


def unpack(package):
    data=base64.b64decode(PACKAGE_B64)
    if hashlib.sha256(data).hexdigest()!=PACKAGE_SHA256:raise RuntimeError('Embedded package was truncated or changed while copying')
    package.mkdir(parents=True,exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        for item in z.infolist():
            if item.is_dir():continue
            rel=Path(item.filename)
            if rel.is_absolute() or '..' in rel.parts:raise ValueError('Invalid embedded path')
            dest=package/rel
            if dest.is_symlink():raise ValueError('A bundled file path is unexpectedly a symlink')
            content=z.read(item)
            if not dest.exists() or hashlib.sha256(dest.read_bytes()).digest()!=hashlib.sha256(content).digest():
                dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(content)


def stop(process):
    if process is not None and process.poll() is None:
        try:os.killpg(process.pid,signal.SIGINT)
        except ProcessLookupError:pass
        try:process.wait(timeout=10)
        except subprocess.TimeoutExpired:
            try:os.killpg(process.pid,signal.SIGKILL)
            except ProcessLookupError:pass
            process.wait()


def environment(root,shared):
    env=os.environ.copy()
    for key in list(env):
        if key.startswith(('UV_','PIP_')) or key in {'PYTHONHOME','PYTHONPATH','VIRTUAL_ENV','CONDA_PREFIX','LD_PRELOAD'}:env.pop(key,None)
    env['LD_LIBRARY_PATH']=':'.join(p for p in env.get('LD_LIBRARY_PATH','').split(':')
        if p and 'site-packages' not in p and 'dist-packages' not in p and not p.startswith('/usr/local/cuda'))
    env.update(PYTHONNOUSERSITE='1',PYTHONUNBUFFERED='1',PIP_CONFIG_FILE=os.devnull,
        PIP_DISABLE_PIP_VERSION_CHECK='1',UV_NO_CONFIG='1',UV_CACHE_DIR=str(shared/'uv-cache'),
        UV_PYTHON_INSTALL_DIR=str(shared/'python'),UV_PYTHON_BIN_DIR=str(shared/'python-bin'),
        UV_LINK_MODE='hardlink',UV_HTTP_TIMEOUT='180',UV_HTTP_RETRIES='3',UV_CONCURRENT_DOWNLOADS='4',
        TMPDIR=str(root/'tmp'),HF_HOME=str(shared/'huggingface'),HF_HUB_DISABLE_TELEMETRY='1',
        DO_NOT_TRACK='1',GIT_TERMINAL_PROMPT='0',VIDEO_LAB_ROOT=str(root),VIDEO_LAB_PACKAGE=str(root/'package'))
    for name in ['WAN_ROOT','LTX_ROOT','SKYREELS_ROOT','OTA_ROOT','KANDINSKY_ROOT']:env[name]=str(root)
    return env


class Controller:
    def __init__(self,root,env):
        self.root,self.env=root,env
        self.state={'model':MODEL['id'],'started':time.time(),'stages':[],'gpu_inference_verified':False}
    def save(self):
        (self.root/'run_state.json').write_text(json.dumps(self.state,indent=2))
    def run(self,name,command,env=None,attempts=1,cwd=None):
        command=list(map(str,command));log=self.root/'logs'/(name+'.log')
        print('\n=== '+name.upper()+' ===',flush=True)
        print(' '.join(command),flush=True)
        entry={'name':name,'command':command,'log':str(log),'started':time.time(),'status':'running'}
        self.state['stages'].append(entry);self.save()
        for attempt in range(1,attempts+1):
            started=time.monotonic()
            with log.open('a') as f:
                f.write('\n$ '+' '.join(command)+'\n');f.flush()
                process=subprocess.Popen(command,cwd=cwd,env=env or self.env,
                    stdout=f,stderr=subprocess.STDOUT,start_new_session=True)
                try:
                    while True:
                        try:rc=process.wait(timeout=20);break
                        except subprocess.TimeoutExpired:
                            print(f'  {name}: running ({int(time.monotonic()-started)}s), log {log.name}',flush=True)
                except BaseException:
                    stop(process);entry.update(status='interrupted',finished=time.time());self.save();raise
            if rc==0:
                entry.update(status='passed',finished=time.time(),attempt=attempt);self.save()
                tail=log.read_text(errors='replace')[-1400:].strip()
                if tail:print(tail,flush=True)
                return
            if attempt<attempts:
                print(f'{name} failed; retrying {attempt+1}/{attempts} using the existing cache.',flush=True)
                time.sleep(attempt*2)
        entry.update(status='failed',finished=time.time(),exit_code=rc);self.save()
        print(log.read_text(errors='replace')[-14000:],flush=True)
        raise RuntimeError(f'{name} failed (exit {rc}). Full log: {log}')


def hardware(root,args):
    if platform.system()!='Linux' or platform.machine()!='x86_64':
        raise RuntimeError('This file targets Linux x86_64, such as the Ubuntu runtime supplied by Colab')
    if not shutil.which('nvidia-smi'):raise RuntimeError('Select Runtime > Change runtime type > GPU in Colab before running this file')
    query=subprocess.check_output(['nvidia-smi','--query-gpu=name,compute_cap,memory.total,memory.free,driver_version',
        '--format=csv,noheader,nounits'],text=True,timeout=20).splitlines()[0]
    row=next(csv.reader([query]));name,cap,total,free,driver=[x.strip() for x in row]
    major=int(cap.split('.')[0]);vram=float(total)/1024;freev=float(free)/1024
    memory={}
    for line in Path('/proc/meminfo').read_text().splitlines():
        key,value=line.split(':',1);memory[key]=int(value.split()[0])*1024
    info={'gpu':name,'compute_capability':cap,'total_vram_gib':round(vram,2),
        'free_vram_gib':round(freev,2),'driver':driver,'host_total_ram_gib':round(memory['MemTotal']/2**30,2),
        'host_available_ram_gib':round(memory['MemAvailable']/2**30,2),'disk_free_gib':round(shutil.disk_usage(root).free/2**30,2),
        'notebook_or_host_python':sys.version,'model_python':MODEL['python']}
    (root/'host.json').write_text(json.dumps(info,indent=2));print(json.dumps(info,indent=2),flush=True)
    guard=MODEL['hardware']
    experimental=args.experimental_t4 and MODEL['id']=='one_to_all' and major==7
    if args.experimental_t4 and MODEL['id']!='one_to_all':raise ValueError('--experimental-t4 applies only to One-to-All')
    if not experimental:
        if major<guard.get('min_compute_major',0):raise RuntimeError(guard.get('unsupported_message','This recipe requires a native BF16 GPU such as L4/A100; T4 is not supported'))
        if vram<guard.get('min_vram_gib',0):raise RuntimeError(f"{MODEL['label']} requires >= {guard['min_vram_gib']} GiB VRAM for this recipe. Select {guard.get('recommended','a larger GPU')}.")
        if freev<guard.get('min_free_vram_gib',0):raise RuntimeError('Not enough free GPU memory. Stop the earlier model process or reconnect an idle GPU runtime.')
    elif vram<14:raise RuntimeError('Even the experimental T4 route requires a 16GB-class GPU')
    if major>=guard.get('max_compute_major_exclusive',999):raise RuntimeError('This pinned CUDA 12.4 stack targets T4/L4/A100; select one of those GPUs')
    if info['host_total_ram_gib']<guard.get('min_ram_gib',0):raise RuntimeError(f"This recipe requires at least {guard['min_ram_gib']} GiB host RAM. Select a high-RAM Colab runtime.")
    if not (root/'venv/bin/python').exists() and info['disk_free_gib']<guard.get('min_disk_gib',0):
        raise RuntimeError(f"Initial installation/download needs >= {guard['min_disk_gib']} GiB free disk; detected {info['disk_free_gib']} GiB")
    if experimental:print('EXPERIMENTAL T4 FP16 + CPU offload selected explicitly; numerical stability and memory fit are unverified.',flush=True)
    return info


def system_tools(controller):
    tools=['ffmpeg','ffprobe']+(['git'] if MODEL.get('needs_git') else [])
    missing=[name for name in tools if not shutil.which(name)]
    if not missing:return
    if not Path('/etc/debian_version').exists() or os.geteuid()!=0:
        raise RuntimeError('Missing system tools: '+', '.join(missing)+'. On Ubuntu install git and ffmpeg, then run again.')
    controller.run('ubuntu_package_index',['apt-get','update','-qq'])
    packages=['ffmpeg','ca-certificates']+(['git'] if MODEL.get('needs_git') else [])
    controller.run('ubuntu_system_tools',['apt-get','install','-y','--no-install-recommends']+packages)


def bootstrap(controller,root,shared):
    boot=root/'bootstrap';boot.mkdir(exist_ok=True)
    uv_env=controller.env.copy();uv_env['PYTHONPATH']=str(boot)
    uv=[sys.executable,'-m','uv','--no-config']
    probe=subprocess.run([sys.executable,'-m','uv','--version'],env=uv_env,capture_output=True,text=True)
    if probe.returncode or probe.stdout.strip()!='uv 0.13.6':
        controller.run('uv_bootstrap',[sys.executable,'-m','pip','install','--isolated','--no-deps','--only-binary=:all:',
            '--upgrade','--target',boot,'--index-url','https://pypi.org/simple','uv==0.13.6'],attempts=2)
    py=root/'venv/bin/python'
    controller.run('managed_python',uv+['python','install',MODEL['python']],env=uv_env,attempts=2)
    if not py.exists():controller.run('create_environment',uv+['venv','--python',MODEL['python'],'--managed-python',root/'venv'],env=uv_env)
    controller.run('interpreter_check',[py,'-c','import sys; assert sys.prefix != sys.base_prefix; assert sys.version.split()[0]==sys.argv[1]; print(sys.executable,sys.version)',MODEL['python']])
    lock=root/'package'/MODEL['requirements']
    expected={'python':MODEL['python'],'lock_sha256':digest(lock),'torch_backend':MODEL['torch_backend']}
    marker=root/'environment.json'
    current=json.loads(marker.read_text()) if marker.exists() else None
    if current!=expected:
        controller.run('install',uv+['pip','sync','--python',py,'--torch-backend',MODEL['torch_backend'],
            '--default-index','https://pypi.org/simple',lock],env=uv_env,attempts=2)
    else:print('Reusing the existing version-pinned environment.',flush=True)
    install_values={'python':str(py),'root':str(root),'package':str(root/'package')}
    for stage in MODEL.get('post_install_stages',[]):
        controller.run(stage['name'],substitute(stage['argv'],install_values))
    controller.run('dependency_check',uv+['pip','check','--python',py],env=uv_env)
    controller.run('resolved_versions',uv+['pip','freeze','--python',py],env=uv_env)
    marker.write_text(json.dumps(expected,indent=2))
    return py


def substitute(command,values):
    return [str(part).format_map(values) for part in command]


def export(root,controller,args,video=None):
    archive=root/(MODEL['id']+'_results_and_logs.zip')
    try:
        with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED) as z:
            for folder in [root/'logs',root/'outputs',root/'previews']:
                if folder.exists():
                    for path in sorted(folder.rglob('*')):
                        if path.is_file() and not path.is_symlink():z.write(path,str(path.relative_to(root)))
            for name in ['host.json','environment.json','run_state.json','failure.json','latest_output.json','hardware.json',
                'preflight.json','backend.log','backend_check.json','model_downloads.json','source_inventory.json',
                'source_patches.diff','run_config.json','selected_cache.json']:
                p=root/name
                if p.exists():z.write(p,name)
            for pattern in ['*/*.json','*/*.txt']:
                for p in sorted((root/'runs').glob(pattern)):
                    if p.is_file():z.write(p,str(p.relative_to(root)))
            z.write(root/'package'/MODEL['requirements'],'requirements.lock')
        print('\nRESULTS / DIAGNOSTICS:',archive,flush=True)
        if video is not None and in_notebook():
            from IPython.display import Video,display
            display(Video(str(video),embed=True))
        if AUTO_DOWNLOAD and not args.no_download and in_notebook():
            try:
                from google.colab import files
                files.download(str(archive))
            except ImportError:pass
            except Exception as error:print('Automatic browser download unavailable:',type(error).__name__,'. Use the Colab file panel.')
    except Exception as error:
        print('Could not build the export ZIP:',str(error),'. Logs remain in',root/'logs',flush=True)


def entrypoint():
    args=arguments()
    if args.action=='info':
        print(json.dumps(MODEL,indent=2));return
    base=Path('/content/open_video_models') if Path('/content').is_dir() else Path.cwd()/'open_video_models'
    root=(args.root or base/MODEL['id']).expanduser().resolve();shared=base/'shared'
    for folder in [root,root/'logs',root/'tmp',root/'outputs',root/'runs',shared]:folder.mkdir(parents=True,exist_ok=True)
    unpack(root/'package')
    if args.action=='extract':print('Bundled example and helpers:',root/'package');return
    (root/'failure.json').unlink(missing_ok=True)
    env=environment(root,shared);controller=Controller(root,env);video=None
    try:
        print('\n'+MODEL['label'],flush=True)
        host=hardware(root,args)
        system_tools(controller)
        if args.action in {'all','setup'}:py=bootstrap(controller,root,shared)
        else:
            py=root/'venv/bin/python'
            if not py.exists():raise RuntimeError('This model environment is missing. Run with --action all or setup first.')
        defaults=dict(MODEL['defaults'])
        if args.prepare_only and MODEL['id']!='one_to_all':raise ValueError('--prepare-only applies only to One-to-All')
        if args.run_custom and MODEL['id']!='one_to_all':raise ValueError('--run-custom applies only to One-to-All')
        if args.offload is not None and MODEL['id']!='ltx':raise ValueError('--offload applies only to LTX; other recipes choose their own offload strategy')
        for key,wanted in MODEL.get('fixed_settings',{}).items():
            requested=getattr(args,key,None)
            if requested is not None and requested!=wanted:
                raise ValueError(f'{key} is fixed at {wanted} for this model recipe')
        for key in ['width','height','frames','fps','steps','seed','offload']:
            if getattr(args,key,None) is not None:defaults[key]=getattr(args,key)
        if args.prompt is not None:defaults['prompt']=args.prompt
        image=Path(args.image).expanduser().resolve() if args.image else root/'package'/MODEL['example_image']
        driver=Path(args.driver).expanduser().resolve() if args.driver else root/'package'/MODEL.get('example_driver','inputs/example.mp4')
        if not image.is_file():raise FileNotFoundError('Input image not found: '+str(image))
        if MODEL['id']=='one_to_all' and not driver.is_file():raise FileNotFoundError('Driving video not found: '+str(driver))
        fingerprint={'model':MODEL['id'],'package':PACKAGE_SHA256,'settings':defaults,'image_sha256':digest(image),
            'driver_sha256':digest(driver) if MODEL['id']=='one_to_all' else None,'experimental_t4':args.experimental_t4}
        known_example=True
        if MODEL['id']=='one_to_all':
            known_example=(fingerprint['image_sha256']==MODEL['example_image_sha256'] and fingerprint['driver_sha256']==MODEL['example_driver_sha256'])
        runid=hashlib.sha256(json.dumps(fingerprint,sort_keys=True).encode()).hexdigest()[:16]
        if args.force:runid+='_'+uuid.uuid4().hex[:6]
        runroot=root/'runs'/runid;runroot.mkdir(parents=True,exist_ok=True)
        outdir=root/'outputs'/runid;outdir.mkdir(parents=True,exist_ok=True)
        output=outdir/('video_'+str(time.time_ns())+'.mp4')
        values={**defaults,'root':str(root),'package':str(root/'package'),'python':str(py),
            'image':str(image),'driver':str(driver),'output':str(output),'cache':str(shared/'huggingface')}
        values['dtype']='fp16' if args.experimental_t4 else 'bf16'
        (runroot/'settings.json').write_text(json.dumps(fingerprint,indent=2))
        for stage in MODEL['setup_stages']:
            command=substitute(stage['argv'],values)
            if args.experimental_t4 and stage.get('experimental_args'):command+=stage['experimental_args']
            controller.run(stage['name'],command)
        if args.action=='setup':
            print('\nSETUP PASSED. To generate without reinstalling, use --action run.',flush=True);return
        complete=runroot/'complete.json'
        if complete.exists() and not args.force and not args.prepare_only:
            previous=json.loads(complete.read_text());p=Path(previous['video'])
            if p.is_file() and digest(p)==previous['sha256']:
                video=p;controller.state.update(status='reused_completed_result',video=str(video),gpu_inference_verified=True);controller.save()
                print('Reusing this exact completed example:',video,flush=True);return
        for stage in MODEL['download_stages']:
            controller.run(stage['name'],substitute(stage['argv'],values),attempts=3)
        offline=controller.env.copy();offline.update(MODEL.get('post_download_offline_env',{}))
        generation_started=time.time()
        (root/'latest_output.json').unlink(missing_ok=True)
        for stage in MODEL['run_stages']:
            command=substitute(stage['argv'],values)
            if args.experimental_t4 and stage.get('experimental_args'):command+=stage['experimental_args']
            if args.run_custom and stage['name']=='inference' and MODEL['id']=='one_to_all':command+=['--run-custom']
            controller.run(stage['name'],command,env=offline)
            if stage['name']=='prepare' and (args.prepare_only or not known_example and not args.run_custom):
                controller.state.update(status='pose_prepared');controller.save()
                print('Pose preparation finished. Previews:',root/'previews',flush=True)
                print('For custom inputs, inspect the previews and rerun with --run-custom to generate.',flush=True);return
        if output.is_file():video=output
        elif (root/'latest_output.json').exists():
            result=json.loads((root/'latest_output.json').read_text())
            candidate=result.get('path') or result.get('video') or result.get('output')
            if candidate:video=Path(candidate)
        if video is None:
            candidates=[p for p in (root/'outputs').rglob('*.mp4') if p.stat().st_mtime>=generation_started-0.25]
            if candidates:video=max(candidates,key=lambda p:p.stat().st_mtime)
        if video is None or not video.is_file() or video.stat().st_size<1024:raise RuntimeError('Generation returned without a new nonempty MP4. Check the inference log.')
        controller.run('verify_video',['ffprobe','-v','error','-select_streams','v:0','-count_frames',
            '-show_entries','stream=codec_name,width,height,pix_fmt,nb_read_frames,avg_frame_rate','-of','json',video])
        text=(root/'logs/verify_video.log').read_text()
        metadata=json.loads(text[text.rfind('\n{')+1:])
        streams=metadata.get('streams',[])
        if not streams:raise RuntimeError('MP4 has no readable video stream')
        stream=streams[0]
        if stream.get('codec_name')!='h264' or stream.get('pix_fmt')!='yuv420p':
            raise RuntimeError('Expected H.264/yuv420p video output')
        if int(stream.get('nb_read_frames','0'))!=int(defaults['frames']):
            raise RuntimeError('Decoded frame count does not match the requested example')
        if stream.get('width')!=int(defaults['width']) or stream.get('height')!=int(defaults['height']):
            raise RuntimeError('Encoded dimensions do not match the requested example')
        numerator,denominator=map(int,stream['avg_frame_rate'].split('/'))
        if abs(numerator/denominator-int(defaults['fps']))>0.01:raise RuntimeError('Encoded FPS does not match the requested example')
        report={'video':str(video),'sha256':digest(video),'video_metadata':stream,'settings':fingerprint,'completed':time.time()}
        complete.write_text(json.dumps(report,indent=2))
        controller.state.update(status='completed',video=str(video),gpu_inference_verified=True);controller.save()
        print('\nSUCCESS:',video,flush=True)
    except BaseException as error:
        (root/'failure.json').write_text(json.dumps({'error':str(error),'traceback':traceback.format_exc(),'time':time.time()},indent=2))
        controller.state.update(status='failed',error=str(error));controller.save()
        raise
    finally:
        export(root,controller,args,video)


